import os, stat, hashlib, json, traceback
from pathlib import Path

work = Path('/work')
claude = work / 'CLAUDE.md'
agents = work / 'AGENTS.md'

report = {}

def path_info(p: Path):
    info = {'path': str(p), 'exists': p.exists(), 'lexists': os.path.lexists(p)}
    try:
        st = os.lstat(p)
        info.update({
            'mode_octal': oct(st.st_mode & 0o7777),
            'uid': st.st_uid,
            'gid': st.st_gid,
            'is_symlink': stat.S_ISLNK(st.st_mode),
            'is_regular': stat.S_ISREG(st.st_mode),
            'is_dir': stat.S_ISDIR(st.st_mode),
        })
        if stat.S_ISLNK(st.st_mode):
            try:
                info['link_target'] = os.readlink(p)
            except Exception as e:
                info['link_target_error'] = repr(e)
    except FileNotFoundError:
        info['lstat_error'] = 'FileNotFoundError'
    except Exception as e:
        info['lstat_error'] = repr(e)
    return info

report['initial_work'] = path_info(work)
report['initial_claude'] = path_info(claude)
report['initial_agents'] = path_info(agents)

claude_bytes = None
if os.path.lexists(claude):
    try:
        # Read as inert bytes, preserving exactly.
        claude_bytes = claude.read_bytes()
        report['claude_read'] = {'ok': True, 'size': len(claude_bytes), 'sha256': hashlib.sha256(claude_bytes).hexdigest()}
    except Exception as e:
        report['claude_read'] = {'ok': False, 'error': repr(e), 'traceback': traceback.format_exc()}
else:
    report['claude_read'] = {'ok': False, 'error': 'CLAUDE.md path does not exist (including symlink)'}

# Create/overwrite AGENTS.md as regular file with identical bytes when readable.
if claude_bytes is not None:
    try:
        with open(agents, 'wb') as f:
            f.write(claude_bytes)
        report['write_agents'] = {'ok': True}
    except Exception as e:
        report['write_agents'] = {'ok': False, 'error': repr(e), 'traceback': traceback.format_exc()}

# Verify AGENTS content/regularity
report['postwrite_agents'] = path_info(agents)
if agents.exists() and claude_bytes is not None:
    try:
        ab = agents.read_bytes()
        report['agents_verify'] = {
            'ok': True,
            'size': len(ab),
            'sha256': hashlib.sha256(ab).hexdigest(),
            'byte_equal_to_claude': ab == claude_bytes,
        }
    except Exception as e:
        report['agents_verify'] = {'ok': False, 'error': repr(e), 'traceback': traceback.format_exc()}

# Attempt to remove old CLAUDE.md entry.
remove_attempts = []
if os.path.lexists(claude):
    # try unlink
    try:
        os.unlink(claude)
        remove_attempts.append({'method': 'os.unlink', 'ok': True})
    except Exception as e:
        remove_attempts.append({'method': 'os.unlink', 'ok': False, 'error': repr(e)})

    # if still exists, try replace via rename to backup then delete backup
    if os.path.lexists(claude):
        tmp = work / 'CLAUDE.md.to_delete_tmp'
        try:
            os.replace(claude, tmp)
            remove_attempts.append({'method': 'os.replace_to_tmp', 'ok': True})
            try:
                os.unlink(tmp)
                remove_attempts.append({'method': 'os.unlink_tmp', 'ok': True})
            except Exception as e:
                remove_attempts.append({'method': 'os.unlink_tmp', 'ok': False, 'error': repr(e)})
        except Exception as e:
            remove_attempts.append({'method': 'os.replace_to_tmp', 'ok': False, 'error': repr(e)})

report['remove_attempts'] = remove_attempts
report['final_claude'] = path_info(claude)
report['final_agents'] = path_info(agents)

print(json.dumps(report, indent=2, sort_keys=True))
